    exp1: "Don't Repeat Yourself。「Pragmatic Programmer」で提唱された原則。同じ知識・ロジックを複数箇所に書かず、1箇所にまとめる(関数化・モジュール化・抽象化)。修正時に1箇所変更すれば済むため、保守性・整合性が大幅向上。ただし過剰なDRY(共通化のしすぎ)はかえって複雑化することもあり、バランスが重要。",
    exp2: "試験では「DRY原則の意味」が問われる。\n\n**覚え方** 🎯 DRY＝**「繰返さない」**。共通部分は1箇所、保守性向上の基本。",
