    exp1: "Keep It Simple, Stupid。米軍由来とされる設計原則で、「設計・実装はできる限りシンプルに保て」を示す。過剰な抽象化・将来のための過剰機能・複雑な依存関係を避け、本当に必要な分だけ作る。YAGNI(You Aren't Gonna Need It)も近い原則。シンプル設計は理解しやすく、バグも少なく、保守も容易。",
