    exp1: "Function Point Method。システムの機能(外部入力・外部出力・外部照会・内部論理ファイル・外部インタフェースファイル)の数と複雑度から「ファンクションポイント」を計算し、規模を見積もる手法。Albrecht提唱(1979)。IFPUG・NESMA・COSMICなど派生がある。LOC見積もりより言語非依存・初期段階見積もりに向く。",
    exp2: "試験では「FP法の考え方」「LOCとの違い」が問われる。\n\n**覚え方** 🎯 ファンクションポイント法＝**「機能数で見積」**。FP、言語非依存、規模見積の標準。",
    exp3: "",
    memory: "ファンクションポイント法＝**「機能数で見積」**。FP、言語非依存、規模見積の標準。",
