    exp1: "Constructive Cost Model。Barry Boehm提唱(1981・改訂版COCOMO II・1995)のソフトウェア開発工数見積もりモデル。コード行数(KSLOC・千行)から工数(人月)・期間・必要人数を経験的な式で計算する。基本COCOMO・中間COCOMO・詳細COCOMOの3レベル。プロジェクト特性(複雑度・信頼性等)で補正。古典的だが現代も参考にされる。",
