    exp1: "Project Management。期限・予算・品質の制約下でプロジェクト目標を達成するため、計画立案・実行・監視・統制・終結を統合的に行う管理活動。PMBOK(知識体系)・PRINCE2・アジャイル等の体系がある。スコープ・スケジュール・コスト・品質・資源・コミュニケーション・リスク・調達・ステークホルダーの統合管理を担う。",
