    exp1: "Project Management Body of Knowledge。米国PMI(Project Management Institute)が発行するプロジェクトマネジメントの知識体系ガイド。世界標準として広く採用。第7版(2021)から従来の「10の知識エリア・5つのプロセスグループ」中心からプリンシプル・パフォーマンスドメインベースに大幅変更。第6版以前は「統合・スコープ・スケジュール・コスト・品質・資源・コミュニケーション・リスク・調達・ステークホルダー」の10エリアで構成。",
