    exp1: "Project Charter。プロジェクトを公式に承認し、PMに権限を与える立ち上げ文書。プロジェクトスポンサー(発注者・経営層)が発行。プロジェクト名・目的・成果物・概要・PM任命・概算予算・スケジュール・主要ステークホルダー・前提条件・制約条件を記載。PMBOKでは立上げプロセスの主要成果物。",
