    exp1: "Project Scope。プロジェクトで実施する作業(プロジェクトスコープ)と作り出す成果物(プロダクトスコープ)の範囲。「何を作るか・何を作らないか」を明確に定義する。曖昧だとスコープクリープ(範囲が次第に膨張する現象)で計画破綻する。WBS・スコープ記述書・要件文書で表現される。",
