    exp1: "Work Breakdown Structure。プロジェクトで実施すべき作業を成果物単位で階層的に分解した構造図(ツリー)。最上位はプロジェクト全体、最下位はワークパッケージ(管理可能な最小単位の作業)。スコープを過不足なく表現し、スケジュール・コスト・資源計画の基盤となる。100%ルール(全作業をカバーし重複なし)が原則。",
