    exp1: "Program Evaluation and Review Technique。タスクの依存関係をノード(タスクまたはイベント)と矢印で表現したネットワーク図。最早開始時刻・最遅開始時刻・余裕(スラック)を計算し、クリティカルパス(プロジェクト最短期間を決定する経路)を発見する。複雑な依存関係を持つプロジェクトの最適化に有効。アローダイアグラム(AOA)とプレシデンス図(AON)の表現形式がある。",
