    exp1: "Critical Path。プロジェクトの完了期間を決定する最長の作業経路。この経路上のタスクは余裕(スラック)がゼロで、1つでも遅れるとプロジェクト全体が遅延する。プロジェクト管理の最重点管理対象。CPM(Critical Path Method)で計算する。複数のクリティカルパスが存在する場合もある。",
    exp2: "試験頻出：「クリティカルパスの特定」「PERTからの計算」が定番計算問題。\n\n**覚え方** 🎯 クリティカルパス＝**「最長経路・遅延禁止」**。プロジェクト全体を律速する重要ルート。",
