    exp1: "Predecessor / Successor Relationship。プロジェクトのタスク間の実行順序・依存関係。あるタスク(先行・予定先)が完了しないと別のタスク(後続)を開始できないという制約。FS(終了-開始)・SS(開始-開始)・FF(終了-終了)・SF(開始-終了)の4タイプがある(最頻出はFS)。リード(前倒し)・ラグ(遅延)も指定可能。",
