    exp1: "Activity On Arrow (AOA)。PERT図の伝統的表記方式。矢印で作業(アクティビティ)を、ノード(円)でイベント(作業の開始点・終了点)を表現する。日本の試験では「アローダイアグラム」と呼ばれることが多い。最早結合点時刻・最遅結合点時刻を計算してクリティカルパスを求める。現代はPDM(AON・Activity On Node)が国際的に主流だが、日本の試験ではAOAも依然出題される。",
