    exp1: "Planned Value。EVMの基本指標の1つ。ある評価時点までに完了している予定の作業に割当てられた計画予算。「スケジュール通りなら、ここまで進んでいるはず」の予算額。BCWS(Budgeted Cost of Work Scheduled・予定作業の予算化コスト)とも呼ばれる旧称。プロジェクト全体のPVの合計はBAC(Budget at Completion・予算合計)。",
    exp2: "試験頻出：EVMの計算問題でPV・EV・ACをセットで使う。\n\n**覚え方** 🎯 PV(計画値)＝**「予定の予算」**。「ここまで進んでるはず」の額。",
