    exp1: "Business Process Reengineering。Michael Hammer提唱(1990)の業務プロセス改革手法。既存プロセスを白紙(クリーンスレート)にし、IT活用を前提に業務プロセスを抜本的に再設計、コスト・速度・品質・サービス等で劇的な改善を狙う。継続改善(BPI・Kaizen)とは異なる「不連続な革新」を目指す。1990年代に流行、現代はDX(デジタルトランスフォーメーション)に発展。",
    exp2: "試験では「BPRの考え方」「Kaizen/BPIとの違い」が問われる。\n\n**覚え方** 🎯 BPR＝**「業務抜本改革」**。Hammer提唱、IT活用で劇的改善、DXの祖。",
    exp3: "",
    memory: "BPR＝**「業務抜本改革」**。Hammer提唱、IT活用で劇的改善、DXの祖。",
